#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024

int main(int argc, char **argv)
{
    const char *input;
    char norm[MAX_INPUT + 1];
    size_t n = 0;
    int is_pal = 1;

    if (argc > 1) {
        input = argv[1];
    } else {
        input = "";
    }

    if (strlen(input) > MAX_INPUT) {
        puts("TOO_LONG");
        return 0;
    }

    for (size_t i = 0; input[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (isalnum(c)) {
            if (isupper(c))
                c = (unsigned char)tolower(c);
            norm[n++] = (char)c;
        }
    }
    norm[n] = '\0';

    for (size_t i = 0, j = n ? n - 1 : 0; i < j; ++i, --j) {
        if (norm[i] != norm[j]) {
            is_pal = 0;
            break;
        }
    }

    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
